const worldButton=document.querySelector('#worldButton'),readButton=document.querySelector('#readButton');
function setMode(reading){document.body.classList.toggle('reading',reading);worldButton.classList.toggle('active',!reading);readButton.classList.toggle('active',reading);worldButton.setAttribute('aria-pressed',String(!reading));readButton.setAttribute('aria-pressed',String(reading));}
worldButton.addEventListener('click',()=>setMode(false));readButton.addEventListener('click',()=>setMode(true));document.querySelectorAll('[data-go]').forEach(button=>button.addEventListener('click',()=>{const target=document.getElementById(button.dataset.go);target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});history.replaceState(null,'','#'+target.id);}));
let audio,oscillators=[],playing=false;document.querySelector('#sound').addEventListener('click',async e=>{if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();const gain=audio.createGain();gain.gain.value=.012;gain.connect(audio.destination);[174.61,261.63,349.23].forEach(f=>{let oscillator=audio.createOscillator();oscillator.frequency.value=f;oscillator.type='sine';oscillator.connect(gain);oscillator.start();oscillators.push(oscillator)});}playing=!playing;if(playing)await audio.resume();else await audio.suspend();e.target.textContent=playing?'Sound on ♫':'Sound off ♫';e.target.setAttribute('aria-pressed',String(playing));});document.querySelector('#year').textContent=new Date().getFullYear();
